{
  "name": "opencode-tandem",
  "version": "0.7.1",
  "description": "Shared agent system prompt and skills for OpenCode, from the tandem-skills repo",
  "keywords": [
    "opencode",
    "tandem-skills",
    "skills"
  ],
  "type": "module",
  "license": "MIT",
  "files": [
    "plugin.js",
    "system-prompt/",
    "skills/"
  ],
  "exports": {
    "./server": "./plugin.js"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/skhoroshavin/tandem-skills.git"
  }
}

import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { assemblePrompt } from "./system-prompt/index.mjs";

const root = dirname(fileURLToPath(import.meta.url));
const prompt = assemblePrompt();

export const Tandem = async () => ({
  config: (config) => {
    config.agent ??= {};
    config.agent.tandem = {
      name: "tandem",
      description: "Pair-programming collaborator: you drive, it navigates and types",
      mode: "primary",
      prompt,
      ...config.agent.tandem,
    };
    if (!config.agent.tandem.disable) config.default_agent ??= "tandem";
    config.skills ??= {};
    config.skills.paths = [...new Set([...(config.skills.paths ?? []), join(root, "skills")])];
  },
});

// Assembles the final system prompt: prefix + body + cli tools + subagent + suffix.
// Parts are joined with a blank line, empty parts are skipped.
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { cliToolsSection } from "./cli-tools/index.mjs";
import { subagentSection } from "./subagent/index.mjs";

const here = dirname(fileURLToPath(import.meta.url));

export function assemblePrompt() {
  const part = (name) => {
    const path = join(here, name);
    return existsSync(path) ? readFileSync(path, "utf8").trim() : "";
  };
  return [
    part("prefix.md"),
    part("prompt.md"),
    cliToolsSection(),
    subagentSection(),
    part("suffix.md"),
  ]
    .filter(Boolean)
    .join("\n\n")
    .concat("\n");
}

// Emits the CLI tools section (prompt.md), keeping only <!--cli:tool--> blocks
// for tools available in this session; empty string when none are.
import { spawnSync } from "node:child_process";
import { readFileSync, statSync } from "node:fs";
import { delimiter, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { filterBlocks } from "../filter.mjs";

const here = dirname(fileURLToPath(import.meta.url));

// windows executables are found via fixed suffixes (.exe etc)
const extensions = process.platform === "win32" ? [".EXE", ".BAT", ".CMD"] : [""];

function isOnPath(binary) {
  for (const dir of (process.env.PATH ?? "").split(delimiter)) {
    for (const ext of extensions) {
      try {
        if (statSync(join(dir, binary + ext)).isFile()) return true;
      } catch {}
    }
  }
  return false;
}

// Chromium-family binary for the headless-render fallback; PATH first, then app bundles
function findBrowserBinary() {
  for (const name of ["chromium", "chromium-browser", "google-chrome", "google-chrome-stable"]) {
    if (isOnPath(name)) return name;
  }
  if (process.platform === "darwin") {
    for (const app of ["Chromium", "Google Chrome"]) {
      const bin = `/Applications/${app}.app/Contents/MacOS/${app}`;
      try {
        if (statSync(bin).isFile()) return bin;
      } catch {}
    }
  }
}

// brew/apt ship a different C++-based html2text with an incompatible CLI;
// only the Python one supports the --ignore-images flag used in the prompt
function isPythonHtml2text() {
  if (!isOnPath("html2text")) return false;
  try {
    const res = spawnSync("html2text", ["--help"], { encoding: "utf8", timeout: 5000 });
    return res.status === 0 && (res.stdout || "").includes("--ignore-images");
  } catch {}
  return false;
}

function toolAvailable(tool, ctx) {
  if (tool === "browser") return ctx.browser !== undefined;
  if (tool === "html2text") return ctx.html2text;
  if (tool === "lynx") return !ctx.html2text && isOnPath(tool);
  if (tool === "osascript") return process.platform === "darwin" && isOnPath(tool);
  return isOnPath(tool);
}

export function cliToolsSection() {
  const ctx = { browser: findBrowserBinary(), html2text: isPythonHtml2text() };
  let hasTools = false;
  const prompt = filterBlocks(readFileSync(join(here, "prompt.md"), "utf8"), (tool) => {
    const available = toolAvailable(tool, ctx);
    hasTools ||= available;
    return available;
  });
  if (!hasTools) return "";
  return prompt
    .replace(/<browser-binary>/g, () => JSON.stringify(ctx.browser))
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

// Emits the subagent section for the method available in this session (paseo
// inside a paseo agent, tmux inside tmux); empty string without one.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { filterBlocks } from "../filter.mjs";

const here = dirname(fileURLToPath(import.meta.url));

const spawnScript = join(
  here,
  process.env.PASEO_AGENT_ID ? "spawn-paseo.sh" : "spawn-tmux.sh",
);

export function subagentSection() {
  const method = process.env.PASEO_AGENT_ID ? "paseo" : process.env.TMUX ? "tmux" : null;
  if (!method) return "";
  return filterBlocks(readFileSync(join(here, "prompt.md"), "utf8"), (name) => name === method)
    .replace(/<spawn-script>/g, () => JSON.stringify(spawnScript))
    .trim();
}
